$handlerForNfrt = [System.Net.Http.HttpClientHandler]::new()
$handlerForNfrt.AllowAutoRedirect = $false
$handlerForNfrt.UseCookies = $false
$handlerForNfrt.UseDefaultCredentials = $false
$clientForNfrt = [System.Net.Http.HttpClient]::new($handlerForNfrt)
$clientForNfrt.Timeout = [TimeSpan]::FromSeconds(20)
$clientForNfrt.DefaultRequestHeaders.UserAgent.ParseAdd('SFM-read-only-identity-review/1')
try {
    $pendingForNfrt = foreach ($requestForNfrt in $requestsForNfrt) {
        @{ request=$requestForNfrt; task=$clientForNfrt.GetAsync($requestForNfrt.url,[System.Net.Http.HttpCompletionOption]::ResponseHeadersRead) }
    }
    $resultsForNfrt = foreach ($pendingRowForNfrt in $pendingForNfrt) {
        try {
            $responseForNfrt = $pendingRowForNfrt.task.GetAwaiter().GetResult()
            try {
                $statusForNfrt=[int]$responseForNfrt.StatusCode
                $valueForNfrt=$null
                $bodyShaForNfrt=$null
                if ($statusForNfrt -eq 200) {
                    $streamForNfrt=$responseForNfrt.Content.ReadAsStreamAsync().GetAwaiter().GetResult()
                    try {
                        $bufferForNfrt=[byte[]]::new(2049)
                        $countForNfrt=0
                        while ($countForNfrt -lt $bufferForNfrt.Length) {
                            $readForNfrt=$streamForNfrt.Read($bufferForNfrt,$countForNfrt,$bufferForNfrt.Length-$countForNfrt)
                            if ($readForNfrt -eq 0) { break }
                            $countForNfrt += $readForNfrt
                        }
                        if ($countForNfrt -gt 2048) { throw 'Checksum response exceeds2048B' }
                        $bodyForNfrt=$bufferForNfrt[0..($countForNfrt-1)]
                        $bodyShaForNfrt=[Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData([byte[]]$bodyForNfrt)).ToLowerInvariant()
                        $textForNfrt=[System.Text.Encoding]::UTF8.GetString([byte[]]$bodyForNfrt).Trim()
                        if ($textForNfrt -match '^[a-fA-F0-9]{64}$') { $valueForNfrt=$textForNfrt.ToLowerInvariant() }
                    } finally { $streamForNfrt.Dispose() }
                }
                [pscustomobject]@{ coordinate=$pendingRowForNfrt.request.coordinate; url=$pendingRowForNfrt.request.url; http_status=$statusForNfrt; checksum_sha256=$valueForNfrt; checksum_body_sha256=$bodyShaForNfrt; matches=($valueForNfrt -eq $pendingRowForNfrt.request.expected); redirect_location=[string]$responseForNfrt.Headers.Location; observed_at=[DateTime]::UtcNow.ToString('o') }
            } finally { $responseForNfrt.Dispose() }
        } catch {
            [pscustomobject]@{coordinate=$pendingRowForNfrt.request.coordinate; url=$pendingRowForNfrt.request.url; http_status=$null; error_type=$_.Exception.GetType().FullName; error=$_.Exception.Message; matches=$false}
        }
    }
    $resultsForNfrt | ConvertTo-Json -Depth 6 -Compress
} finally { $clientForNfrt.Dispose(); $handlerForNfrt.Dispose() }
